snippetBlock:
const rawByPath = import.meta.glob<string>(
  [
    '../snippet/*.{vibe,ts,tsx,elm,json,html,sh,txt}',
    '!../snippet/*.d.vibe.ts',
  ],
  {
    query: '?raw',
    import: 'default',
    eager: true,
  },
)

const highlightedByPath = import.meta.glob<string>(
  [
    '../snippet/*.{vibe,ts,tsx,elm,json,html,sh,txt}',
    '!../snippet/*.d.vibe.ts',
  ],
  { query: '?highlighted', import: 'default', eager: true },
)

postBlock:
const documentByPath = import.meta.glob<unknown>('./post/*.md', {
  eager: true,
  import: 'default',
})

const frontmatterByPath = import.meta.glob<unknown>('./post/*.md', {
  eager: true,
  import: 'frontmatter',
})
